"""Call the running API and compare responses with discovered schemas."""

from __future__ import annotations

import json
import time

import httpx
from fastmcp import FastMCP

from mcp_server.contracts import compare_with_contract, discover_probes
from mcp_server.dependencies import api_base_url

# Generated by FastAPI for request errors. They are not application response models.
_FRAMEWORK_SCHEMAS = {"HTTPValidationError", "ValidationError"}

# Windows often waits about 2 seconds before it refuses a port that is not
# listening. A 2 second connect timeout cancels that handshake, so the probe
# reports "timed out" when the API is still binding or nothing is listening.
_TIMEOUT = httpx.Timeout(5.0, connect=5.0)
_CONNECT_ATTEMPTS = 3
_CONNECT_PAUSE_SECONDS = 0.2


def check_api_health(base_url: str | None = None) -> dict:
    """Call the local API and compare each discovered GET route with its schema.

    Routes come from the FastAPI app in the configured repository, including
    list routes. Nested ``$ref`` values are resolved against that app's OpenAPI
    document. A JSON file in the contracts directory is used when its title
    matches the response schema or, for a list, the item schema. Path
    parameters are filled from schema examples. One failing route is reported
    on its own and does not abort the other routes. Every call probes the
    running API and loads the schema from the current source. When a component
    schema on that process differs from the source, the process is stale and
    its responses are not accepted as a passing contract.
    """
    url = (base_url or api_base_url()).rstrip("/")
    return _probe(url)


def get_contract_violations(base_url: str | None = None) -> dict:
    """Return missing fields, unexpected fields, type errors, and schema mismatches.

    Uses the same discovered probes as check_api_health, including each item
    of a list response, and keeps only the failing checks.
    """
    return violations_from_health(check_api_health(base_url))


def violations_from_health(report: dict) -> dict:
    violations = [
        violation
        for check in report.get("checks") or []
        for violation in check.get("violations") or []
    ]
    return {
        "base_url": report.get("base_url"),
        "reachable": report.get("reachable"),
        "healthy": report.get("healthy"),
        "violation_count": len(violations),
        "violations": violations,
        "stale": bool(report.get("stale")),
        "error": report.get("error"),
    }


def register(mcp: FastMCP) -> None:
    mcp.tool(check_api_health)
    mcp.tool(get_contract_violations)


def _probe(root: str) -> dict:
    discovered = discover_probes()
    if not discovered["ok"]:
        return {
            "base_url": root,
            "reachable": False,
            "healthy": False,
            "stale": False,
            "checks": [],
            "skipped": discovered["skipped"],
            "error": discovered["error"],
        }

    try:
        spec_response = _get_with_retry(f"{root}/openapi.json")
    except httpx.RequestError as exc:
        return _unreachable(root, discovered, exc)

    drift = _drift_from_response(discovered.get("openapi") or {}, spec_response)
    if drift:
        message = _stale_message(drift)
        violation = {
            "path": "/openapi.json",
            "contract": "openapi",
            "kind": "stale_process",
            "field": drift[0]["schema"],
            "message": message,
        }
        return {
            "base_url": root,
            "reachable": True,
            "healthy": False,
            "stale": True,
            "checks": [
                {
                    "name": "GET /openapi.json",
                    "path": "/openapi.json",
                    "contract": "openapi",
                    "status_code": spec_response.status_code,
                    "valid": False,
                    "violations": [violation],
                    "body": None,
                }
            ],
            "skipped": discovered["skipped"],
            "error": message,
        }

    checks = []
    for probe in discovered["probes"]:
        path = str(probe["path"])
        try:
            response = _get_with_retry(f"{root}{path}")
        except httpx.RequestError as exc:
            return _unreachable(root, discovered, exc, checks)
        try:
            checks.append(_check_response(path, probe, response))
        except Exception as exc:
            checks.append(_route_error(probe, path, exc))

    return {
        "base_url": root,
        "reachable": True,
        "healthy": all(check["valid"] for check in checks),
        "stale": False,
        "checks": checks,
        "skipped": discovered["skipped"],
        "error": None,
    }


def schema_drift(disk_spec: dict, live_spec: dict) -> list[dict]:
    """Return shared component schemas whose fields differ between source and process.

    Schemas that exist on only one side are ignored, so a test double that does
    not publish the application's models is still checked by its response body.
    """
    disk_schemas = _component_schemas(disk_spec)
    live_schemas = _component_schemas(live_spec)
    drifted = []
    for name in sorted(set(disk_schemas) & set(live_schemas)):
        if name in _FRAMEWORK_SCHEMAS:
            continue
        disk_shape = _model_shape(disk_schemas[name])
        live_shape = _model_shape(live_schemas[name])
        if disk_shape == live_shape:
            continue
        drifted.append(
            {
                "schema": name,
                "source_properties": list(disk_shape["properties"]),
                "server_properties": list(live_shape["properties"]),
            }
        )
    return drifted


def _component_schemas(spec: object) -> dict:
    if not isinstance(spec, dict):
        return {}
    components = spec.get("components")
    if not isinstance(components, dict):
        return {}
    schemas = components.get("schemas")
    if not isinstance(schemas, dict):
        return {}
    return schemas


def _model_shape(schema: object) -> dict:
    if not isinstance(schema, dict):
        return {"type": None, "required": [], "properties": {}}
    properties = schema.get("properties") or {}
    if not isinstance(properties, dict):
        properties = {}
    shaped = {}
    for name in sorted(properties):
        prop = properties[name]
        if isinstance(prop, dict):
            shaped[name] = {
                "type": prop.get("type"),
                "format": prop.get("format"),
                "ref": prop.get("$ref"),
            }
        else:
            shaped[name] = {"type": None, "format": None, "ref": None}
    required = schema.get("required") or []
    if not isinstance(required, list):
        required = []
    return {
        "type": schema.get("type"),
        "required": sorted(str(item) for item in required),
        "properties": shaped,
    }


def _drift_from_response(disk_spec: dict, response: httpx.Response) -> list[dict]:
    if response.status_code != 200:
        return []
    try:
        live_spec = response.json()
    except json.JSONDecodeError:
        return []
    if not isinstance(live_spec, dict):
        return []
    return schema_drift(disk_spec, live_spec)


def _stale_message(drift: list[dict]) -> str:
    parts = []
    for item in drift:
        server_only = sorted(set(item["server_properties"]) - set(item["source_properties"]))
        source_only = sorted(set(item["source_properties"]) - set(item["server_properties"]))
        detail = []
        if server_only:
            detail.append("server has " + ", ".join(server_only))
        if source_only:
            detail.append("source has " + ", ".join(source_only))
        if not detail:
            detail.append("field types or required fields differ")
        parts.append(f"{item['schema']} ({'; '.join(detail)})")
    return (
        "The running API process is stale and does not match the source on disk: "
        + "; ".join(parts)
        + ". Responses from this process were not accepted. Restart the API and probe again."
    )


def _unreachable(root: str, discovered: dict, exc: Exception, checks: list | None = None) -> dict:
    return {
        "base_url": root,
        "reachable": False,
        "healthy": False,
        "stale": False,
        "checks": checks or [],
        "skipped": discovered["skipped"],
        "error": f"Could not connect to {root}: {exc}",
    }


def _get_with_retry(url: str) -> httpx.Response:
    """Retry a refused or timed-out connection while the API is still starting.

    ``trust_env`` is off so an HTTP proxy does not steal loopback traffic.
    The connect timeout is longer than the Windows refusal delay, so a closed
    port surfaces as connection refused instead of a cancelled handshake.
    """
    last_error: httpx.RequestError | None = None
    for attempt in range(_CONNECT_ATTEMPTS):
        try:
            with httpx.Client(timeout=_TIMEOUT, trust_env=False) as client:
                return client.get(url)
        except httpx.RequestError as exc:
            last_error = exc
            if attempt + 1 == _CONNECT_ATTEMPTS:
                raise
            time.sleep(_CONNECT_PAUSE_SECONDS)
    raise last_error  # pragma: no cover


def _route_error(probe: dict, path: str, exc: Exception) -> dict:
    contract_name = probe.get("contract")
    return {
        "name": probe.get("name"),
        "path": path,
        "contract": contract_name,
        "status_code": None,
        "valid": False,
        "violations": [
            {
                "path": path,
                "contract": contract_name,
                "kind": "schema_mismatch",
                "field": None,
                "message": f"Schema validation failed: {exc}",
            }
        ],
        "body": None,
    }


def _check_response(path: str, probe: dict, response: httpx.Response) -> dict:
    contract_name = probe["contract"]
    violations: list[dict] = []
    payload: object | None = None

    if response.status_code != 200:
        violations.append(
            {
                "path": path,
                "contract": contract_name,
                "kind": "unexpected_status",
                "field": None,
                "message": f"Expected HTTP 200, received {response.status_code}",
            }
        )

    try:
        payload = response.json()
    except json.JSONDecodeError:
        violations.append(
            {
                "path": path,
                "contract": contract_name,
                "kind": "invalid_json",
                "field": None,
                "message": "Response body is not JSON",
            }
        )

    schema = probe.get("schema")
    if payload is not None and schema:
        violations.extend(
            compare_with_contract(
                payload,
                schema,
                path=path,
                contract_name=str(contract_name or "openapi"),
            )
        )

    return {
        "name": probe["name"],
        "path": path,
        "contract": contract_name,
        "status_code": response.status_code,
        "valid": not violations,
        "violations": violations,
        "body": payload,
    }
